    "text": "No âmbito da Teoria Geral dos Sistemas (TGS) aplicada à administração, as organizações são compreendidas como sistemas abertos. Qual parâmetro do sistema é responsável pelo processo de retorno da informação, permitindo o ajuste e a manutenção do equilíbrio do sistema frente às variações do ambiente?",
