    "text": "Burns e Stalker, em suas pesquisas sobre a influência do ambiente nas organizações, classificaram as estruturas em 'mecanicistas' e 'orgânicas'. Assinale a alternativa que descreve corretamente uma característica das estruturas orgânicas.",
