      "Correta. A Sistêmica é mais voltada para a compreensão do 'todo' e das interações; a Contingencial é mais aplicada e relativista.",
      "Incorreta. Ambas consideram o ambiente externo, pois ambas tratam de sistemas abertos.",
      "Incorreta. Ambas consideram múltiplos fatores; a tecnologia e o ambiente são as variáveis independentes principais da Contingencial.",
