      "Incorreta. Esta característica pertence à liderança liberal, onde o grupo tem autonomia total.",
      "Correta. Reflete o foco no líder e a verticalidade das decisões típica do estilo autocrático.",
      "Incorreta. Esta descrição refere-se ao estilo liberal (laissez-faire).",
      "Incorreta. Na liderança autocrática, a produção tende a cair ou parar quando o líder se ausenta."
