    "id": "adm_sim_47",
    "text": "Em todas as organizações, os administradores desempenham funções e papéis que lhes são próprios. Para desempenhá-los, o administrador deve possuir habilidades de três tipos: humanas, técnicas e conceituais. Essas habilidades são exigidas com maior ou menor intensidade, dependendo do nível organizacional em que o administrador atua.\n\nAssim, é correto afirmar que:",
