    "text": "Um papel “é um conjunto de expectativas de comportamento de um gerente” (DAFT, 2010, p. 21). No desempenho de suas funções, os administradores desempenham papéis diversos, agrupados em três categorias, segundo a tipologia proposta por Mintzberg. Uma categoria de papéis envolve os “eventos e situações em que o administrador deve fazer uma escolha ou opção” (CHIAVENATO, 2003, p. 8).\n\nSão papéis dessa categoria:",
