    "text": "Fayol desenvolve a ideia dos quatro pilares principais da Administração, descritos a seguir. Relacione os itens 1, 2, 3 e 4 e suas respectivas definições.\n\n1. Planejar\n2. Organizar\n3. Dirigir\n4. Controlar\n\n( ) Indica a alocação de recursos humanos, financeiros e técnicos que são necessários para atingir as metas propostas.\n( ) Ocorre quando se comparam os resultados obtidos nas organizações com os planos de trabalho, para melhorias e correções.\n( ) Realiza a gestão das propostas estratégicas para que as metas sejam atingidas.\n( ) Está relacionado a estabelecer metas e objetivos que deverão ser atingidos pela organização.\n\nAssinale a alternativa que apresenta a sequência correta de cima para baixo.",
