    "id": "adm_sim_53",
    "text": "As Funções Administrativas são etapas fundamentais para que as estruturas organizacionais obtenham sucesso nos seus projetos. A esse respeito, analise as afirmativas abaixo e atribua valores Verdadeiro (V) ou Falso (F).\n\n( ) Organização é a etapa onde se define o que se deve fazer para atingir os resultados esperados.\n( ) No Planejamento deve-se verificar os recursos disponíveis, definir as tarefas, quem e como vão realizá-las, e quais recursos cada um utilizará.\n( ) No Controle os resultados são analisados para verificar se estão de acordo com o que foi planejado.\n\nAssinale a alternativa que apresenta a sequência correta de cima para baixo.",
