    "id": "adm_sim_63",
    "text": "O Comportamento Organizacional(CO) estuda a dinâmica e o funcionamento das organizações. Segundo Chiavenato(2005), existem três níveis de abordagem do comportamento. Acerca desse assunto, assinale a alternativa incorreta.",
