    "text": "É necessário que uma equipe tenha objetivos para que consiga se manter e se desenvolver. São eles que guiam as ações de participação da equipe, que coordenam e planejam seus esforços. Servem também para delimitar critérios para resolver conflitos interpessoais e para a melhoria do trabalho. Quando uma equipe executa seus trabalhos e atinge níveis ótimos, dizemos que a equipe está em:",
