    "text": "Motivação e liderança são conceitos interligados e estudados na escola de relações humanas. Sobre liderança e o líder, analise as afirmativas abaixo:\nI. Líder de um time é aquele capaz de coordenar esforços para a obtenção de um objetivo comum.\nII. O bom líder é aquele que consegue despertar o que há de melhor no outro, conciliando os interesses individuais e particulares com os objetivos comuns.\nIII. Ao líder é delegado o poder e responsabilidade de facilitar a existência de condições propícias à realização do trabalho.\nAssinale a alternativa correta.",
