    "id": "adm_sim_78",
    "text": "Ano: 2020 Banca: IBFC Órgão: EBSERH Prova: IBFC- 2020- EBSERH- Analista Administrativo\nOs autores Hersey e Blanchard elaboraram a Teoria da Liderança Situacional em 1982 e a consideram como um processo por meio do qual um indivíduo exerce influência sobre determinado grupo, visando atingir um determinado objetivo, em uma situação específica. Sobre a liderança situacional, assinale a alternativa correta.",
    "options": [
      "A) O estilo clássico de comportamento do líder propõe uma abordagem com traços de personalidade adotado pela liderança situacional",
      "B) A proposta bidimensional da liderança situacional aborda a ênfase nas pessoas e na produção de resultados",
      "C) A eficácia da liderança situacional, dependerá da adequação do estilo de liderança ao grau de maturidade dos colaboradores",
      "D) A tomada de decisões da liderança situacional define a participação dos grupos e equipes e fixa a divisão de tarefas com determinantes decisórios",
      "E) A liderança situacional deve ser eficaz no seu desempenho onde os processos administrativos devem ter orientação para a produção e objetivos alcançados"
    ],
    "correctIndex": 2,
    "explanations": [
      "Incorreta. A teoria dos traços de personalidade é uma abordagem clássica e distinta da situacional.",
      "Incorreta. A abordagem bidimensional (foco na produção e nas pessoas) refere-se ao Grid Gerencial de Blake e Mouton.",
      "Correta. O sucesso da liderança situacional baseia-se no diagnóstico da maturidade da equipe e na adaptação do estilo do líder.",
      "Incorreta. A liderança situacional foca na adaptação do comportamento (diretividade e apoio) conforme a maturidade, e não em fixar divisões de tarefas de forma rígida.",
      "Incorreta. A teoria não foca apenas na orientação para a produção, mas no equilíbrio entre comportamento de tarefa e de relação conforme a necessidade dos liderados."
    ],
    "generalExplanation": "A premissa fundamental da Teoria da Liderança Situacional de Hersey e Blanchard é que não existe um único estilo de liderança ideal. A eficácia depende da adequação do estilo do líder ao nível de maturidade (competência e comprometimento) dos liderados para a tarefa específica.",
    "banca": "IBFC",
    "ano": 2020,
