    "id": "adm_sim_80",
    "text": "Ano: 2017 Banca: IBFC Órgão: EMBASA Prova: IBFC- 2017- EMBASA- Agente Administrativo\nMotivos internos para realização do trabalho são aqueles que surgem das próprias pessoas. Assinale a alternativa que não contém um motivo interno.",
