    "text": "Ano: 2020 Banca: IBFC Órgão: EBSERH Prova: IBFC- 2020- EBSERH- Analista Administrativo\nExistem várias formas de transmitir a Cultura Organizacional dentro das organizações. Assinale a alternativa que apresenta as mais comuns.",
