    "text": "Em organizações modernas e matriciais, a necessidade de agilidade exige que a comunicação rompa as barreiras departamentais e os níveis hierárquicos tradicionais. O fluxo que permite a um colaborador de uma unidade técnica comunicar-se diretamente com o gestor de outra área funcional, sem percorrer toda a cadeia de comando, é o:",
