    "text": "De acordo com a Teoria Matemática da Comunicação e as abordagens organizacionais, a comunicação plena só ocorre quando o destinatário compreende o significado da mensagem enviada. Sobre os obstáculos a essa compreensão, assinale a alternativa correta:",
