    "text": "Acerca das funções administrativas, assinale a alternativa que preencha correta e respectivamente as lacunas.\n\"_____ é a fase do processo administrativo que define a divisão do trabalho organizacional a ser feito por meio de tarefas de órgãos ou cargos e cuida da coordenação dos esforços para garantir o alcance do propósito desejado._____ é a fase do processo administrativo que coordena e converge esforços de todas as pessoas para garantir que elas desempenhem suas tarefas de modo a alcançar os objetivos organizacionais com sucesso._____ é a fase do processo administrativo que estabelece os objetivos a serem alcançados e identifica as ações necessárias para atingir tais objetivos._____ é a fase do processo administrativo que monitora o desempenho.\"(Chiavenato, 2005):",
