      "Incorreta. A outorga transfere a titularidade e execução por meio de lei para entes da Administração Indireta, o que não se aplica a concessionárias privadas.",
      "Incorreta. A desconcentração é a divisão de competências interna dentro de uma mesma pessoa jurídica (criação de órgãos), sem transferir a uma nova entidade.",
      "Incorreta. Centralização é a prestação de serviços diretamente pelo próprio ente federativo por meio de seus órgãos internos.",
