      "Correta. Entre a Administração Direta e a Indireta há apenas vinculação jurídica para fins de controle finalístico (tutela administrativa / supervisão ministerial), voltado a garantir o cumprimento das finalidades legais da entidade.",
      "Incorreta. As autarquias gozam de autonomia administrativa, financeira e técnica, mas não de soberania ou autonomia absoluta, sujeitando-se à tutela finalística e ao controle dos Tribunais de Contas.",
      "Incorreta. Autarquias são pessoas jurídicas autônomas resultantes de descentralização, e não órgãos despersonalizados de desconcentração.",
