      "Incorreta. A execução das atividades-fim (missão principal da entidade) compete aos órgãos de linha. O staff atua em atividades-meio ou consultivas de suporte.",
      "Correta. A função essencial do staff (assessoria) é subsidiar os executivos e gerentes de linha com conhecimentos técnicos especializados, análises, estudos, planejamento e assessoria jurídica/estratégica.",
      "Incorreta. Os órgãos de staff coexistem com a linha (estrutura linha-staff) para complementá-la, mantendo-se a cadeia de comando linear nos órgãos executivos.",
