      "Correta. O Princípio da Especialidade estabelece que a entidade da Administração Indireta tem sua capacidade jurídica restrita ao cumprimento estrito dos fins específicos definidos em sua lei instituidora/autorizadora.",
      "Incorreta. O controle sobre a entidade restringe-se à tutela administrativa (controle finalístico de legalidade e alcance de metas), vedada a intervenção arbitrária que viole a autonomia administrativa outorgada por lei.",
