      "Correta. O ciclo estrutural clássico opera da seguinte forma: o gestor delega autoridade (fluxo descendente) para capacitar o liderado a tomar decisões; o liderado assume a responsabilidade pela execução e tem o dever de prestar contas (fluxo ascendente - accountability) dos resultados perante a autoridade.",
