    "text": "Em uma Secretaria de Planejamento, foi instituído um Grupo de Trabalho multidisciplinar para implementar um novo sistema informatizado de compras públicas. Os servidores designados para a iniciativa continuam vinculados e respondendo hierárquica e tecnicamente aos seus respectivos gerentes de departamento fixos (Finanças, RH, Logística), mas recebem diretrizes e ordens diretas do Coordenador Geral do Projeto quanto a prazos, metas operacionais e entregas da implantação. Essa configuração estrutural baseada em dupla subordinação caracteriza uma:",
