    "text": "Um Agente Administrativo atua em um setor de perícia técnica em que as atividades são altamente complexas, envolvem riscos legais elevados e exigem decisões frequentes e consultas contínuas ao superior imediato. De acordo com a teoria da amplitude administrativa (amplitude de controle), esse setor deve apresentar:",
