      "Correta. Fatores como alta complexidade das tarefas, risco elevado de erros, exigência de consultas contínuas e necessidade de controle rigoroso demandam amplitude de controle estreita (poucos subordinados por supervisor), assegurando qualidade e acompanhamento próximo.",
