    "id": "adm_sim_170",
    "text": "O princípio da Unidade de Comando, pilar da cadeia escalar clássica, estabelece que cada subordinado deve reportar-se a apenas um superior. No entanto, a excessiva verticalização e o alongamento da cadeia de comando podem gerar patologias organizacionais, tais como:",
