    "text": "No âmbito da Teoria Geral da Administração, o processo administrativo contemporâneo é composto pelas funções de Planejamento, Organização, Direção e Controle (PODC). Sobre a função Controle, assinale a alternativa que descreve com precisão a sua essência primordial:",
