    "id": "adm_sim_176",
    "text": "A função administrativa precursora que serve de fundamento para todas as demais, sendo responsável por diagnosticar o ambiente, fixar a missão institucional, definir os objetivos estratégicos e traçar os meios de ação necessários para atingi-los, é denominada:",
