    "id": "adm_sim_182",
    "text": "Durante a execução das operações do Censo Demográfico pelo IBGE, a administração central precisa assegurar que milhares de recenseadores não sobreponham suas áreas de cobertura censitária e que todos sigam rigorosamente as mesmas diretrizes metodológicas. Esse esforço deliberado de evitar duplicidades de tarefas e garantir a unidade de ação corresponde à:",
