      "Correta. A função Organização estabelece o arranjo estrutural, a divisão do trabalho, os departamentos e a alocação de recursos ('quem faz o quê'). A Coordenação, por sua vez, atua no fluxo do trabalho, sincronizando tempos, ritmos e esforços para que as unidades operem de forma harmônica e integrada ('como e quando').",
