      "Correta. Na visão moderna e gerencial, o controle não é uma finalidade punitiva ou burocrática em si mesma, mas um instrumento indispensável de governança e suporte decisório, orientado à retroalimentação, ao aprendizado organizacional e à entrega eficiente de valor ao cidadão.",
