    "id": "adm_sim_185",
    "text": "No contexto do controle administrativo e da avaliação de desempenho institucional, a doutrina consagra a análise multidimensional em eficiência, eficácia e efetividade. Quando um Assistente Técnico Administrativo foca suas métricas de controle estritamente no “atingimento das metas quantitativas” e na “entrega do produto final previsto”, ele está priorizando a dimensão da:",
