    "id": "adm_sim_186",
    "text": "Um Técnico Administrativo do IBGE, designado para estruturar uma nova agência regional, precisa distribuir tarefas e fluxos de trabalho entre os servidores, definir as linhas de responsabilidade de cada função e alocar os equipamentos e materiais necessários ao funcionamento do setor. De acordo com o processo administrativo, essa atuação enquadra-se predominantemente na função de:",
