    "text": "Com base na Teoria Contingencial da Administração e nos estudos seminais de Lawrence e Lorsch sobre desenho organizacional, a necessidade de mecanismos de integração (coordenação) em uma instituição pública ou privada é diretamente proporcional ao grau de:",
