    "text": "O processo de controle administrativo segue um fluxo lógico e sequencial para garantir que a organização mantenha seu equilíbrio e alcance seus objetivos. De acordo com a literatura técnica da Administração Geral, assinale a alternativa que apresenta a sequência correta das etapas do processo de controle:",
