    "text": "No âmbito da Gestão da Qualidade, o Programa 5S é amplamente utilizado para a organização, disciplina e otimização do ambiente de trabalho. O senso que se refere especificamente à necessidade de “separar o necessário do desnecessário”, eliminando o que não agrega valor ao processo e descartando o excesso, é o:",
