    "id": "adm_sim_229",
    "text": "Henry Mintzberg identificou dez papéis gerenciais desempenhados pelos administradores no dia a dia organizacional, agrupados em três categorias principais: interpessoais, informacionais e decisórios. O papel gerencial interpessoal caracterizado por estabelecer e manter uma rede de contatos, tanto internos quanto externos à instituição (como parceiros, fornecedores e outros administradores), para troca de informações e captação de favores, é o de:",
    "options": [
      "A) Líder.",
      "B) Símbolo (ou Figura de Proa).",
      "C) Contato (ou Elemento de Ligação).",
      "D) Monitor (ou Coletor).",
      "E) Disseminador."
    ],
    "correctIndex": 2,
    "explanations": [
      "Incorreta. O papel de Líder é exercido no âmbito majoritariamente interno e foca em motivar, guiar, engajar e treinar os subordinados organizacionais.",
      "Incorreta. O papel de Símbolo (ou Figura de Proa) envolve representar formal e oficialmente a organização em eventos, solenidades, atos legais e cerimônias sociais.",
      "Correta. O papel de Contato (ou Elemento de Ligação / Liaison) representa o estabelecimento e manutenção de uma rede de relacionamentos (rede de contatos externa e interna) para troca fluida de informações e cooperação.",
      "Incorreta. O papel de Monitor (ou Coletor) pertence à categoria de papéis informacionais e refere-se à atividade de rastrear e coletar informações úteis para a organização.",
      "Incorreta. O papel de Disseminador também é informacional e consiste em transmitir as informações coletadas para os membros internos da equipe organizadora."
    ],
    "generalExplanation": "Nos 10 Papéis Gerenciais de Mintzberg, o papel interpessoal de 'Contato' (ou Elemento de Ligação / Liaison) consiste em criar e manter uma rede de contatos internos e externos para obtenção de informações e apoio. Gabarito C.",
