      "Correta. A Habilidade representa a dimensão prática e técnica da competência. Refere-se à capacidade psicomotora do indivíduo de aplicar na prática, por meio do treino, experiência e repetição, o conhecimento que ele detém (o 'Saber Fazer').",
      "Incorreta. A proatividade, ética, vontade e motivação pertencem à dimensão da Atitude (o 'Querer Fazer').",
