    "generalExplanation": "Modelo do CHA das Competências: Conhecimento = Saber (Teoria); Habilidade = Saber Fazer (Prática/Técnica/Aplicação); Atitude = Querer Fazer (Comportamento/Postura). Gabarito B.",
