    "text": "A evolução histórica da gestão da qualidade perpassou diferentes eras: Inspeção, Controle Estatístico, Garantia da Qualidade e Gestão da Qualidade Total. Assinale a alternativa que descreve uma característica central da Era da Garantia da Qualidade:",
