      "Correta. A Era da Garantia da Qualidade introduziu a cultura da prevenção (evitar que o erro ocorra por meio do planejamento rigoroso, engenharia de processos e normas de certificação de sistemas, como as normas ISO), integrando setores de projetos, compras e produção.",
